package com.musiccatalog.service; import com.musiccatalog.dto.AlbumDtos.*; import com.musiccatalog.entity.*; import com.musiccatalog.exception.ApiException; import com.musiccatalog.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class LibraryService { private final AlbumRepository albums;private final UserRepository users; public LibraryService(AlbumRepository a,UserRepository u){albums=a;users=u;} private User user(String email){return users.findByEmail(email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));} private LibraryAlbum dto(Album a){return new LibraryAlbum(a.getId(),a.getAppleCatalogId(),a.getTitle(),a.getArtistName(),a.getGenre(),a.getReleaseDate(),a.getTrackCount(),a.getArtworkUrl(),a.getUserRating(),a.getUserNotes(),a.getCreatedAt(),a.getUpdatedAt());} @Transactional(readOnly=true) public List<LibraryAlbum> all(String email){return albums.findAllByUserIdOrderByCreatedAtDesc(user(email).getId()).stream().map(this::dto).toList();} public LibraryAlbum add(String email,AddAlbum d){User u=user(email);if(albums.existsByUserIdAndAppleCatalogId(u.getId(),d.appleCatalogId()))throw new ApiException(HttpStatus.CONFLICT,"This album is already in your library");Album a=new Album();a.setUser(u);a.setAppleCatalogId(d.appleCatalogId());a.setTitle(d.title());a.setArtistName(d.artistName());a.setGenre(d.genre());a.setReleaseDate(d.releaseDate());a.setTrackCount(d.trackCount());a.setArtworkUrl(d.artworkUrl());return dto(albums.save(a));} public LibraryAlbum update(String email,Long id,UpdateAlbum d){Album a=albums.findByIdAndUserId(id,user(email).getId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Album not found"));a.setUserRating(d.userRating());a.setUserNotes(d.userNotes());return dto(a);} public void delete(String email,Long id){Album a=albums.findByIdAndUserId(id,user(email).getId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Album not found"));albums.delete(a);} }
